        this.decoder = new StringDecoder('utf8');
        this.socket = socket;
        resolve(socket);
      });
    });
  }

  private onData(chunk: Buffer): void {
    this.buffer += this.decoder.write(chunk);
    const match = RESPONSE_TERMINATOR.exec(this.buffer);
